<script setup>import {ref,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,useSession,toast,labels} from '../core';import State from '../components/State.vue';import Icon from '../components/Icon.vue';const route=useRoute(),router=useRouter(),session=useSession(),pet=ref(null),loading=ref(true),error=ref(''),busy=ref(false);async function load(){loading.value=true;error.value='';try{pet.value=await api('/pets/'+route.params.id)}catch(e){error.value=e.message}finally{loading.value=false}}async function apply(){if(!session.user){router.push({path:'/login',query:{next:route.fullPath}});return}busy.value=true;try{await api('/pets/'+pet.value.id+'/applications','POST');toast('申请已提交，可以在我的领养查看进度');router.push('/adoptions')}catch(e){toast(e.message,true)}finally{busy.value=false}}onMounted(load);watch(()=>route.params.id,load);</script><template><section class="shell section"><RouterLink to="/pets" class="breadcrumb">← 返回寻找伙伴</RouterLink><State :loading="loading" :error="error" @retry="load"/><div v-if="pet&&!loading&&!error" class="detail-grid"><div class="detail-image"><img :src="pet.image" :alt="pet.name"/></div><article class="detail-copy"><p class="eyebrow">A FRIEND FOR LIFE</p><span class="badge">{{labels[pet.status]}}</span><h1>你好，我是{{pet.name}}。</h1><p class="detail-lead">{{pet.breed}} · {{pet.category==='cat'?'猫咪':'狗狗'}}</p><p class="location"><Icon name="pin"/>{{pet.province}} {{pet.region}}</p><hr><h3>关于我</h3><p class="preserve">{{pet.description||'发布者还没有填写更多介绍，欢迎联系了解。'}}</p><div class="contact-panel"><h4>联系发布者 · {{pet.publisherName}}</h4><template v-if="pet.canContact"><p v-if="pet.phone">电话：{{pet.phone}}</p><p v-if="pet.wechat">微信：{{pet.wechat}}</p><p v-if="pet.email">邮箱：{{pet.email}}</p></template><p v-else>{{session.user?'当前状态下，联系方式仅对交接当事人开放。':'登录后可查看待领养伙伴的联系方式。'}}</p></div><button v-if="!pet.isOwner&&pet.status==='AVAILABLE'" class="btn wide" :disabled="busy" @click="apply"><Icon name="heart"/>{{busy?'正在提交…':'我想给它一个家'}}</button><RouterLink v-if="pet.isOwner" to="/adoptions" class="btn wide">查看收到的申请 <Icon name="arrow"/></RouterLink><p class="hint">请先充分沟通并确认养宠条件。双方完成交接后分别确认，才会记录领养成功。</p></article></div></section></template>
